35	
36	export interface MatrixOption extends ComponentOption, BoxLayoutOptionMixin {
37	    mainType?: 'matrix';
38	    x?: MatrixDimensionOption;
39	    y?: MatrixDimensionOption;
40	    body?: MatrixBodyOption;
41	    corner?: MatrixCornerOption;
42	    // Only for the matrix overall style, won't be inherited by x/y/coner/body.
43	    backgroundStyle?: ItemStyleOption;
44	    // Used on the outer border and the divider line.
45	    borderZ2?: number;
46	    tooltip?: CommonTooltipOption<MatrixTooltipFormatterParams>;
47	
48	    // PENDING: do we need to support other states, i.e., `emphasis`, `blur`, `select`?
49	}
50	
51	interface MatrixBodyCornerBaseOption extends MatrixCellStyleOption {
52	    /**
53	     * Only specify some special cell definitions.
54	     * It can represent both body cells and top-left corner cells.
55	     *
56	     * [body/corner cell locating]:
57	     *  The rule is uniformly applied, such as, in `matrix.dataToPoint`
58	     *  and `matrix.dataToLayout` and `xxxComponent.coord`.
59	     *  Suppose the matrix.x/y dimensions (header) are defined as:
60	     *  matrix: {
61	     *      x: [{ value: 'Xa0', children: ['Xb0', 'Xb1'] }, 'Xa1'],
62	     *      y: [{ value: 'Ya0', children: ['Yb0', 'Yb1'] }],
63	     *  }
64	     *  -----------------------------------------
65	     *  |       |       |     Xa0       |       |
66	     *  |-------+-------+---------------|  Xa1  |
67	     *  |cornerQ|cornerP|  Xb0  |  Xb1  |       |
68	     *  |-------+-------+-------+-------+--------
69	     *  |       |  Yb0  | bodyR | bodyS |       |
70	     *  |  Ya0  |-------+-------+---------------|
71	     *  |       |  Yb1  |       |     bodyT     |
72	     *  |---------------|------------------------
73	     *  "Locator number" (`MatrixXYLocator`):
74	     *    The term `locator` refers to a integer number to locate cells on x or y direction.
75	     *    Use the top-left cell of the body as the origin point (0, 0),
76	     *      the non-negative locator indicates the right/bottom of the origin point;
77	     *      the negative locator indicates the left/top of the origin point.
78	     *  "Ordinal number" (`OrdinalNumber`):
79	     *    This term follows the same meaning as that in category axis of cartesian. They are
80	     *    non-negative integer, designating each string `matrix.x.data[i].value`/`matrix.y.data[i].value`.
81	     *    'Xb0', 'Xb2', 'Xa1', 'Xa0' are assigned with the ordinal numbers 0, 1, 2, 3.
82	     *    For every leaf dimension cell, `OrdinalNumber` and `MatrixXYLocator` is the same.
83	     *
84	     *  A cell or pixel point or rect can be determined/located by a pair of `MatrixCoordValueOption`.
85	     *  See also `MatrixBodyCornerCellOption['coord']`.
86	     *
87	     *  - The body cell `bodyS` above can be located by:
88	     *      - `coord: [1, 0]` (`MatrixXYLocator` or `OrdinalNumber`, which is a non-negative integer)
89	     *      - `coord: ['Xb1', 'Yb0']`
90	     *      - `coord: ['Xb1', 0]` (mix them)
91	     *  - The corner cell `cornerQ` above can be located by:
92	     *      - `coord: [-2, -1]` (negative `MatrixXYLocator`)
93	     *      - But it is NOT supported to use `coord: ['Y1_0', 'X1_0']` (XY transposed form) here.
94	     *        It's mathematically sound, but may introduce confusion and unnecessary
95	     *        complexity (consider the 'Xa1' case), and corner locating is not frequently used.
96	     *  - `mergeCells`: Body cells or corner cells can be merged, such as "bodyT" above, an input
97	     *      - The merging can be defined by:
98	     *        `matrix.data[i]: {coord: [['Xb1', 'Xa1'], 'Yb0'], mergeCells: true}`.
99	     *      - Input `['Xa1', 'Yb1']` to `dataToPoint` will get a point in the center of "bodyT".
100	     *      - Input `['Xa1', 'Yb1']` to `dataToLayout` will get a rect of the "bodyT".
101	     *  - If inputing a non-leaf dimension cell to locate, such as `['Xa0', 'Yb0']`,
102	     *      - it returns only according to the center of the dimension cells, regardless of the body span.
103	     *        (therefore, the result can be on the boundary of two body cells.)
104	     *        And the oridinal number assigned to 'Xa0' is 3, thus input `[3, 'Yb0']` get the some result.
105	     *  - The dimension (header) cell can be located by negative `MatrixXYLocator`. For example:
106	     *      - The center of the node 'Ya0' can be located by `[-2, 'Ya0']`.
107	     */
108	    data?: MatrixBodyCornerCellOption[];
109	}
110	export interface MatrixBodyOption extends MatrixBodyCornerBaseOption {
111	}
112	export interface MatrixCornerOption extends MatrixBodyCornerBaseOption {
113	}
114	
115	/**
116	 * Commonly used as `MatrixCoordRangeOption[]`
117	 * Can locate a cell or a rect range of cells.
118	 * `[2, 8]` indicates a cell.
119	 * `[2, null/undefined/NaN]` means y is the entire column.
120	 * `[null/undefined/NaN, 8]` is the opposite.
121	 * `[[2, 5], 8]` indicates a rect of cells in x range of `2~5` and y `8`.
122	 * `[[2, 5], null/undefined/NaN]` indicates a x range of `2~5` and y is the entire column.
123	 * `[[2, 5], [7, 8]]` indicates a rect of cells in x range of `2~5` and y range of `7~8`.
124	 * `['aNonLeaf', 8]` indicates a rect of cells in x range of `aNonLeaf` and y `8`.
125	 * @see {parseCoordRangeOption}
126	 * @see {MatrixBodyCornerBaseOption['data']}
127	 */
128	export type MatrixCoordRangeOption = (MatrixCoordValueOption | MatrixCoordValueOption[] | NullUndefined);
129	/**
130	 * `OrdinalRawValue` is originally provided by `matrix.x/y.data[i].value` or `series.data`.
131	 */
132	export type MatrixCoordValueOption = OrdinalRawValue | OrdinalNumber | MatrixXYLocator;
133	
134	
135	export interface MatrixBaseCellOption extends MatrixCellStyleOption {
136	}
137	
138	export interface MatrixBodyCornerCellOption extends MatrixBaseCellOption {
139	    // Text that can be displayed.
140	    value?: string;
141	    // Use it to reference a coord in matrix.
142	    coord?: MatrixCoordRangeOption[];
143	    // Merge cells determined by `coord`.
144	    mergeCells?: boolean;
145	}
146	
147	interface MatrixDimensionOption extends MatrixCellStyleOption, MatrixDimensionLevelOption {
148	    type?: 'category'; // For internal usage; force be 'category'.
149	    show?: boolean;
150	    data?: MatrixDimensionCellLooseOption[];
151	    // `levels[0]`: the topmost (for x dimension) or leftmost (for y dimension) level.
152	    // If not specified, use null/undefined, such as `levels: [null, null, {levelSize: 10}]`
153	    levels?: (MatrixDimensionLevelOption | NullUndefined)[];
154	    dividerLineStyle?: LineStyleOption;
155	}
156	
157	export interface MatrixDimensionCellOption extends MatrixBaseCellOption {
158	    // Use it to define a coord in matrix.
159	    // Do not use type `OrdinalRawValue` here. Number input is forbiden due to the possible confusion.
160	    // e.g., if `matrix.x.data: [1, 2, 3]` is allowed, then querying `coord: [1, null]` will actually get
161	    // the second column, since number represents the index (i.e. `MatrixXYLocator` or `OrdinalNumber`).
162	    value?: string;
163	    // column width (for x dimension) or row height (for y dimension).
164	    // If not specified (null/undefined), auto calculate it.
165	    // Only available on leaves, to avoid unnecessary complex.
166	    // If it is a percentage, such as '30%', based on the matrix width/height, rather than the canvas size.
167	    size?: PositionSizeOption;
168	    children?: MatrixDimensionCellOption[];
169	}
170	export type MatrixDimensionCellLooseOption = MatrixDimensionCellOption | MatrixDimensionCellOption['value'];
171	
172	export interface MatrixDimensionLevelOption {
173	    // `matrix.levelSize` specifies the default size of every tree levels.
174	    // `matrix.levels[i].levelSize` specifies the size of a certain level.
175	    // For x dimension, that is height; for y dimension, that is width.
176	    // If not specified (null/undefined), auto calculate it.
177	    // If it is a percentage, such as '30%', based on the matrix width/height, rather than the canvas size.
178	    levelSize?: PositionSizeOption;
179	    // Other level specific options may added if needed, such as border-bottom/right style.
180	}
181	
182	export interface MatrixDimensionModel extends Model<MatrixDimensionOption> {
183	}
184	
185	/**
186	 * Two levels of cascade inheritance:
187	 *  - priority-high: style options defined in `matrix.x/y/coner/body.data[i]` (in cell)
188	 *  - priority-low: style options defined in `matrix.x/y/coner/body`
189	 */
190	export interface MatrixCellStyleOption {
191	    // [NOTE - padding]:
192	    //  - Consider the option for the space between cell boundary to text, percentage value for
193	    //    `label.width/height` is not supported, because it is not ideal - the padding would vary
194	    //    with the cell size, making the layout inconsistent.
195	    //  - The inner text padding uses `lable.style.padding`.
196	    //    The text truncation rect is obtained by cell rect minus by padding.
197	    //  - The inner series / other coord sys padding is not supported, to avoid necessary complexity.
198	    //    Consider some series, such as heatmap, prefer no padding.
199	    label?: LabelOption;
200	    itemStyle?: ItemStyleOption;
201	    cursor?: string;
202	    // By default, auto decide whether to be silent, considering tooltip.
203	    silent?: boolean | NullUndefined;
204	    // Used when style conflict - especially for thick border style.
205	    z2?: number;
206	}
207	
208	export interface MatrixTooltipFormatterParams {
209	    componentType: 'matrix'
210	    matrixIndex: number
211	    name: string
212	    $vars: ['name', 'xyLocator']
213	}
214	
215	const defaultLabelOption: LabelOption = {
216	    show: true,
217	    color: tokens.color.secondary,
218	    // overflow: 'truncate',
219	    overflow: 'break',
220	    lineOverflow: 'truncate',
221	    padding: [2, 3, 2, 3],
222	    // Prefer to use `padding`, rather than distance.
223	    distance: 0,
224	};
225	function makeDefaultCellItemStyleOption(isCorner: boolean) {
226	    return {
227	        color: 'none',
228	        borderWidth: 1,
229	        borderColor: isCorner ? 'none' : tokens.color.borderTint,
230	    };
231	};
232	const defaultDimOption: MatrixDimensionOption = {
233	    show: true,
234	    label: defaultLabelOption,
235	    itemStyle: makeDefaultCellItemStyleOption(false),
236	    silent: undefined,
237	    dividerLineStyle: {
238	        width: 1,
239	        color: tokens.color.border,
240	    },
241	};
242	const defaultBodyOption: MatrixBodyOption = {
243	    label: defaultLabelOption,
244	    itemStyle: makeDefaultCellItemStyleOption(false),
245	    silent: undefined,
246	};
247	const defaultCornerOption: MatrixCornerOption = {
248	    label: defaultLabelOption,
249	    itemStyle: makeDefaultCellItemStyleOption(true),
250	    silent: undefined,
251	};
252	const defaultMatrixOption: MatrixOption = {
253	    // As a most basic coord sys, `z` should be lower than
254	    // other series and coord sys, such as, grid.
255	    z: -50,
256	    left: '10%',
257	    top: '10%',
258	    right: '10%',
259	    bottom: '10%',
260	    x: defaultDimOption,
261	    y: defaultDimOption,
262	    body: defaultBodyOption,
263	    corner: defaultCornerOption,
264	    backgroundStyle: {
265	        color: 'none',
266	        borderColor: tokens.color.axisLine,
267	        borderWidth: 1,
268	    },
269	};
270	
271	
272	class MatrixModel extends ComponentModel<MatrixOption> implements CoordinateSystemHostModel {
273	    static type = 'matrix';
274	    type = MatrixModel.type;
275	
276	    coordinateSystem: Matrix;
277	
278	    static layoutMode = 'box' as const;
279	
280	    private _dimModels: {
281	        x: MatrixDimensionModel;
282	        y: MatrixDimensionModel;
283	    };
284	
285	    private _body: MatrixBodyCorner<'body'>;
286	    private _corner: MatrixBodyCorner<'corner'>;
287	
288	    static defaultOption: MatrixOption = defaultMatrixOption;
289	
290	    optionUpdated(): void {
291	        // Simply re-create all to follow model changes.
292	
293	        const dimModels = this._dimModels = {
294	            // Do not use matrixModel as the parent model, for preventing from cascade-fetching options to it.
295	            x: new MatrixDimensionModel(this.get('x', true) || {}),
296	            y: new MatrixDimensionModel(this.get('y', true) || {}),
297	        };
298	
299	        dimModels.x.option.type = dimModels.y.option.type = 'category';
300	        const xDim = dimModels.x.dim = new MatrixDim('x', dimModels.x);
301	        const yDim = dimModels.y.dim = new MatrixDim('y', dimModels.y);
302	
303	        const dims = {x: xDim, y: yDim};
304	        this._body = new MatrixBodyCorner(
305	            'body', new Model(this.getShallow('body')), dims
306	        );
307	        this._corner = new MatrixBodyCorner(
308	            'corner', new Model(this.getShallow('corner')), dims
309	        );
310	    }
311	
312	    getDimensionModel(dim: 'x' | 'y'): MatrixDimensionModel {
313	        return this._dimModels[dim];
314	    }
315	
316	    getBody(): MatrixBodyCorner<'body'> {
317	        return this._body;
318	    }
319	
320	    getCorner(): MatrixBodyCorner<'corner'> {
321	        return this._corner;
322	    }
323	
324	}
325	
326	export class MatrixDimensionModel extends Model<MatrixDimensionOption> {
327	    dim: MatrixDim;
328	    getOrdinalMeta(): OrdinalMeta {
329	        return this.dim.getOrdinalMeta();
330	    }
331	}
332	
333	export default MatrixModel;
